=== server.js ===
import express from "express";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import crypto from "node:crypto";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = path.join(__dirname, "data.json");
const SLOT_HOURS = [9, 10, 11, 13, 14, 15, 16, 17, 18, 19, 20];
const SESSION_TTL_MS = 8 * 3600 * 1000;

function hashPassword(password, salt = crypto.randomBytes(16).toString("hex")) {
  return `${salt}:${crypto.scryptSync(password, salt, 64).toString("hex")}`;
}
function verifyPassword(password, stored) {
  const [salt, hash] = String(stored || "").split(":");
  if (!salt || !hash) return false;
  const a = Buffer.from(hash, "hex");
  const b = crypto.scryptSync(password, salt, 64);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function load() {
  if (fs.existsSync(DATA_FILE)) return JSON.parse(fs.readFileSync(DATA_FILE, "utf8"));
  let adminPassword = process.env.ADMIN_PASSWORD;
  if (!adminPassword) {
    adminPassword = crypto.randomBytes(9).toString("base64url");
    console.log(`관리자 초기 비밀번호 (ID: admin): ${adminPassword}`);
  }
  return {
    admins: [{ id: "admin", username: "admin", passwordHash: hashPassword(adminPassword) }],
    trainers: [
      { id: "t1", name: "김코치" },
      { id: "t2", name: "이코치" },
    ],
    members: [],
    bookings: [],
  };
}
let db = load();
function save() {
  fs.writeFileSync(DATA_FILE, JSON.stringify(db, null, 2));
}
const id = () => crypto.randomUUID();
const publicMember = ({ passwordHash, ...m }) => m;

const app = express();
app.use(express.json({ limit: "10kb" }));
app.use(express.static(path.join(__dirname, "public")));

function fail(res, status, message) {
  return res.status(status).json({ error: message });
}

// 요청 횟수 제한 (IP + 구간별, 메모리 기반)
function rateLimit({ windowMs, max, name }) {
  const hits = new Map();
  return (req, res, next) => {
    const key = `${name}:${req.ip}`;
    const now = Date.now();
    const entry = hits.get(key);
    if (!entry || now - entry.start > windowMs) {
      hits.set(key, { start: now, count: 1 });
      return next();
    }
    entry.count += 1;
    if (entry.count > max) {
      res.set("Retry-After", String(Math.ceil((entry.start + windowMs - now) / 1000)));
      return fail(res, 429, "요청이 너무 많습니다. 잠시 후 다시 시도하세요.");
    }
    next();
  };
}
const loginLimit = rateLimit({ name: "login", windowMs: 15 * 60 * 1000, max: 10 });
const writeLimit = rateLimit({ name: "write", windowMs: 60 * 1000, max: 30 });
app.use("/api", rateLimit({ name: "api", windowMs: 60 * 1000, max: 300 }));

// 세션 (메모리)
const sessions = new Map();
function auth(req, res, next) {
  const token = (req.get("Authorization") || "").replace(/^Bearer /, "");
  const session = token && sessions.get(token);
  if (!session || session.expires < Date.now()) {
    if (session) sessions.delete(token);
    return fail(res, 401, "로그인이 필요합니다.");
  }
  if (session.role === "member" && !db.members.some((m) => m.id === session.userId)) return fail(res, 401, "로그인이 필요합니다.");
  req.user = session;
  next();
}
const adminOnly = (req, res, next) => (req.user.role === "admin" ? next() : fail(res, 403, "관리자만 할 수 있습니다."));
const canAccessMember = (user, memberId) => user.role === "admin" || user.userId === memberId;

app.post("/api/login", loginLimit, (req, res) => {
  const { role, username, password } = req.body;
  const login = String(username || "").trim();
  const pw = String(password || "");
  let userId = null;
  if (role === "admin") {
    const admin = db.admins.find((a) => a.username === login);
    if (admin && verifyPassword(pw, admin.passwordHash)) userId = admin.id;
  } else {
    const member = db.members.find((m) => m.phone === login);
    if (member && verifyPassword(pw, member.passwordHash)) userId = member.id;
  }
  if (!userId) return fail(res, 401, "아이디 또는 비밀번호가 올바르지 않습니다.");
  const token = crypto.randomBytes(32).toString("hex");
  const userRole = role === "admin" ? "admin" : "member";
  sessions.set(token, { userId, role: userRole, expires: Date.now() + SESSION_TTL_MS });
  res.json({ token, role: userRole, userId });
});

app.post("/api/logout", auth, (req, res) => {
  sessions.delete((req.get("Authorization") || "").replace(/^Bearer /, ""));
  res.json({ ok: true });
});

app.use("/api", auth);

app.get("/api/trainers", (_req, res) => res.json(db.trainers));

app.get("/api/members", (req, res) => {
  const list = db.members.filter((m) => canAccessMember(req.user, m.id));
  res.json(list.map(publicMember));
});

app.post("/api/members", writeLimit, adminOnly, (req, res) => {
  const name = String(req.body.name || "").trim();
  const phone = String(req.body.phone || "").trim();
  const password = String(req.body.password || "");
  if (!name) return fail(res, 400, "이름을 입력하세요.");
  if (!/^[0-9-]{9,13}$/.test(phone)) return fail(res, 400, "전화번호 형식이 올바르지 않습니다.");
  if (password.length < 8) return fail(res, 400, "비밀번호는 8자 이상이어야 합니다.");
  if (db.members.some((m) => m.phone === phone)) return fail(res, 409, "이미 등록된 전화번호입니다.");
  const member = { id: id(), name, phone, passwordHash: hashPassword(password), remaining: 0, history: [] };
  db.members.push(member);
  save();
  res.status(201).json(publicMember(member));
});

// 회원권 충전 (횟수 추가) - 관리자 전용
app.post("/api/members/:id/passes", writeLimit, adminOnly, (req, res) => {
  const member = db.members.find((m) => m.id === req.params.id);
  if (!member) return fail(res, 404, "회원을 찾을 수 없습니다.");
  const count = Number(req.body.count);
  if (!Number.isInteger(count) || count <= 0 || count > 200) return fail(res, 400, "충전 횟수는 1~200 사이 정수여야 합니다.");
  member.remaining += count;
  member.history.push({ at: new Date().toISOString(), change: count, reason: "회원권 충전" });
  save();
  res.json(publicMember(member));
});

app.get("/api/slots", (req, res) => {
  const { trainerId, date } = req.query;
  if (!trainerId || !/^\d{4}-\d{2}-\d{2}$/.test(String(date))) return fail(res, 400, "트레이너와 날짜를 지정하세요.");
  const now = Date.now();
  const slots = SLOT_HOURS.map((h) => {
    const start = `${date}T${String(h).padStart(2, "0")}:00`;
    const taken = db.bookings.some((b) => b.trainerId === trainerId && b.start === start && b.status === "booked");
    const past = new Date(start).getTime() <= now;
    return { start, available: !taken && !past };
  });
  res.json(slots);
});

app.get("/api/bookings", (req, res) => {
  let { memberId } = req.query;
  if (req.user.role !== "admin") {
    if (memberId && memberId !== req.user.userId) return fail(res, 403, "다른 회원의 예약은 볼 수 없습니다.");
    memberId = req.user.userId;
  }
  const list = db.bookings
    .filter((b) => !memberId || b.memberId === memberId)
    .sort((a, b) => a.start.localeCompare(b.start));
  res.json(list);
});

app.post("/api/bookings", writeLimit, (req, res) => {
  const { memberId, trainerId, start } = req.body;
  if (!canAccessMember(req.user, memberId)) return fail(res, 403, "본인 예약만 할 수 있습니다.");
  const member = db.members.find((m) => m.id === memberId);
  const trainer = db.trainers.find((t) => t.id === trainerId);
  if (!member) return fail(res, 404, "회원을 찾을 수 없습니다.");
  if (!trainer) return fail(res, 404, "트레이너를 찾을 수 없습니다.");
  if (typeof start !== "string" || !/^\d{4}-\d{2}-\d{2}T\d{2}:00$/.test(start)) return fail(res, 400, "잘못된 시간입니다.");
  const hour = Number(start.slice(11, 13));
  if (!SLOT_HOURS.includes(hour)) return fail(res, 400, "예약 가능한 시간이 아닙니다.");
  if (new Date(start).getTime() <= Date.now()) return fail(res, 400, "지난 시간은 예약할 수 없습니다.");
  if (member.remaining <= 0) return fail(res, 400, "남은 PT 횟수가 없습니다. 회원권을 충전하세요.");
  const active = (b) => b.status === "booked" && b.start === start;
  if (db.bookings.some((b) => active(b) && b.trainerId === trainerId)) return fail(res, 409, "이미 예약된 시간입니다.");
  if (db.bookings.some((b) => active(b) && b.memberId === memberId)) return fail(res, 409, "같은 시간에 다른 예약이 있습니다.");

  member.remaining -= 1;
  member.history.push({ at: new Date().toISOString(), change: -1, reason: `PT 예약 ${start} (${trainer.name})` });
  const booking = { id: id(), memberId, memberName: member.name, trainerId, trainerName: trainer.name, start, status: "booked" };
  db.bookings.push(booking);
  save();
  res.status(201).json(booking);
});

// 취소: 수업 24시간 전까지는 횟수 복구, 이후는 차감 유지
app.post("/api/bookings/:id/cancel", writeLimit, (req, res) => {
  const booking = db.bookings.find((b) => b.id === req.params.id);
  if (!booking || !canAccessMember(req.user, booking.memberId)) return fail(res, 404, "예약을 찾을 수 없습니다.");
  if (booking.status !== "booked") return fail(res, 400, "취소할 수 없는 예약입니다.");
  const startMs = new Date(booking.start).getTime();
  if (startMs <= Date.now()) return fail(res, 400, "이미 시작된 수업은 취소할 수 없습니다.");
  const member = db.members.find((m) => m.id === booking.memberId);
  const refundable = startMs - Date.now() >= 24 * 3600 * 1000;
  booking.status = "cancelled";
  if (member && refundable) {
    member.remaining += 1;
    member.history.push({ at: new Date().toISOString(), change: 1, reason: `예약 취소 ${booking.start}` });
  } else if (member) {
    member.history.push({ at: new Date().toISOString(), change: 0, reason: `당일 취소 (횟수 차감 유지) ${booking.start}` });
  }
  save();
  res.json({ booking, refunded: refundable });
});

// 수업 완료 처리 - 관리자 전용
app.post("/api/bookings/:id/complete", writeLimit, adminOnly, (req, res) => {
  const booking = db.bookings.find((b) => b.id === req.params.id);
  if (!booking) return fail(res, 404, "예약을 찾을 수 없습니다.");
  if (booking.status !== "booked") return fail(res, 400, "완료 처리할 수 없는 예약입니다.");
  booking.status = "done";
  save();
  res.json(booking);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`http://localhost:${PORT}`));

